<script lang="ts">
 import { onMount } from 'svelte'
 import VoiceOrb from './VoiceOrb.svelte'
 let {skin='cloud',level=0,animate=true,phase='Ready'}:{skin?:string;level?:number;animate?:boolean;phase?:string}=$props()
 let time=$state(0)
 const speed=$derived(phase.includes('Speaking')?2.7:phase.includes('Listening')?1.8:.75)
 const power=$derived(Math.min(1,Math.max(0,level)))
 onMount(()=>{let frame=0,last=0;const tick=(now:number)=>{frame=requestAnimationFrame(tick);if(document.hidden||now-last<33)return;const dt=Math.min(.1,(now-last)/1000);last=now;if(animate)time+=dt*speed};frame=requestAnimationFrame(tick);return()=>cancelAnimationFrame(frame)})
</script>
<div class="visual" data-skin={skin} style={`--lens-glow:${.65+power*.5+Math.sin(time*2)*.08};--lens-size:${1+power*.25};--lens-halo:${.5+power*.5}`}>
 {#if skin==='lens'}<div class="lens-skin"><svg viewBox="0 0 220 220" aria-hidden="true"><defs><radialGradient id="bezel"><stop stop-color="#42474a"/><stop offset=".72" stop-color="#181a1c"/><stop offset=".9" stop-color="#606466"/><stop offset=".94" stop-color="#2a2d2f"/><stop offset="1" stop-color="#080a0b"/></radialGradient><radialGradient id="glass"><stop stop-color="#a41c0c"/><stop offset=".35" stop-color="#410704"/><stop offset=".8" stop-color="#160506"/><stop offset="1" stop-color="#030405"/></radialGradient><radialGradient id="red-glow"><stop stop-color="#fff1b2"/><stop offset=".16" stop-color="#ffc04d"/><stop offset=".4" stop-color="#f83f13"/><stop offset=".72" stop-color="#a61207" stop-opacity=".7"/><stop offset="1" stop-color="#9b1006" stop-opacity="0"/></radialGradient><radialGradient id="lens-halo"><stop stop-color="#fa310c" stop-opacity=".4"/><stop offset="1" stop-color="#af130b" stop-opacity="0"/></radialGradient></defs><circle cx="110" cy="110" r="105" fill="url(#bezel)"/><circle cx="110" cy="110" r="92" fill="#090b0d" stroke="#141617" stroke-width="3"/><circle cx="110" cy="110" r="82" fill="url(#glass)" stroke="#747b7c" stroke-opacity=".25"/><circle cx="110" cy="110" r="76" fill="none" stroke="#6b2115" stroke-opacity=".45" stroke-width=".8"/><circle class="lens-halo" cx="110" cy="110" r="73" fill="url(#lens-halo)"/><circle class="lens-core" cx="110" cy="110" r="35" fill="url(#red-glow)"/><ellipse cx="85" cy="66" rx="24" ry="8" fill="#fff" opacity=".045" transform="rotate(-30 85 66)"/><path d="M52 141a67 67 0 0 0 102 20" fill="none" stroke="#bf4831" stroke-opacity=".12" stroke-width="2"/><circle cx="110" cy="110" r="100" fill="none" stroke="#ced3d2" stroke-opacity=".12"/></svg></div>
 {:else if skin==='scanner'}<div class="scanner-case" aria-hidden="true">{#each Array(8) as _,i}<i style={`--led:${.04+Math.max(0,1-Math.abs(i-(Math.sin(time)*.5+.5)*7)/2.2)*(.55+power*.45)}`}></i>{/each}</div>
 {:else}<VoiceOrb {level} {animate}/>{/if}
</div>
<style>
.visual{position:relative;width:100%;height:100%;display:grid;place-items:center}.lens-skin{width:100%;height:100%}.lens-skin svg{width:100%;height:100%}.lens-skin :global(.lens-core){transform-origin:110px 110px;transform:scale(var(--lens-size));opacity:var(--lens-glow)}.lens-skin :global(.lens-halo){opacity:var(--lens-halo)}.scanner-case{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:6px;width:min(336px,calc(100vw - 48px));height:50px;padding:12px 15px;background:#080909;border:1px solid #393939;border-radius:8px;box-shadow:inset 0 1px 3px #000}.scanner-case i{flex:1;height:23px;border-radius:2px;background:rgb(190 28 12 / var(--led));box-shadow:0 0 12px rgb(220 30 10 / calc(var(--led)*.25))}
</style>
